public class Foo {

    private int[] foo() {
        bar(new SomeInterface() {
            @Override
            public Object run() {
                baz();
                return null;
            }
        });

        return new int[0];
    }
}

interface SomeInterface {
    Object run();
}

public class Foo {

    private int[] foo() {
        bar(() -> {
            baz();
            return null;
        });

        return new int[0];
    }
}

